23	export const runScenario = (scenario: Scenario): { results: Result[] } => {
24	  const { customer, steps } = scenario;
25	  const results: Result[] = [];
26	  const priorPayoutsByPolicy = new Map<number, number>();
27	  let quoteCount = 0;
28	
29	  steps.forEach((step) => {
30	    if (step.op === "quote") {
31	      results.push({ premium: quote(customer, step.items, quoteCount) });
32	      quoteCount += 1;
33	    } else {
34	      const policyStep = steps[step.policy] as QuoteStep;
35	      const priorPayouts = priorPayoutsByPolicy.get(step.policy) ?? 0;
36	      const result = claim(policyStep.items, step.incident, priorPayouts);
37	      priorPayoutsByPolicy.set(step.policy, priorPayouts + result.payout);
38	      results.push(result);
39	    }
40	  });
41	
42	  return { results };
43	};
